(function () {
    'use strict';

    /* Mobile nav */
    const hbg = document.getElementById('hbg');
    const hbgIc = document.getElementById('hbg-icon');
    const nl = document.getElementById('nav-links');
    hbg.addEventListener('click', () => {
        const o = nl.classList.toggle('open');
        hbgIc.className = o ? 'fa-solid fa-xmark' : 'fa-solid fa-bars';
    });
    nl.querySelectorAll('.nl,.nav-cta').forEach(l => l.addEventListener('click', () => {
        nl.classList.remove('open');
        hbgIc.className = 'fa-solid fa-bars';
    }));

    /* Active nav on scroll */
    const secs = document.querySelectorAll('section[id]');
    const nls = document.querySelectorAll('.nl');
    window.addEventListener('scroll', () => {
        let cur = '';
        secs.forEach(s => { if (window.scrollY >= s.offsetTop - 80) cur = s.id; });
        nls.forEach(l => {
            l.classList.remove('on');
            if (l.getAttribute('href') === '#' + cur) l.classList.add('on');
        });
    }, { passive: true });

    /* Intersection fade-in */
    const io = new IntersectionObserver((entries) => {
        entries.forEach(e => { if (e.isIntersecting) { e.target.classList.add('vis'); io.unobserve(e.target); } });
    }, { threshold: 0.1 });
    document.querySelectorAll('.fi').forEach(el => io.observe(el));

    /* Count-up stats */
    const cio = new IntersectionObserver((entries) => {
        entries.forEach(e => {
            if (!e.isIntersecting) return;
            const el = e.target;
            const end = parseInt(el.dataset.count, 10);
            let n = 0, step = Math.ceil(end / 50);
            const t = setInterval(() => {
                n = Math.min(n + step, end);
                el.textContent = n + '+';
                if (n >= end) clearInterval(t);
            }, 28);
            cio.unobserve(el);
        });
    }, { threshold: 0.5 });
    document.querySelectorAll('[data-count]').forEach(el => cio.observe(el));

    /* GitHub contribution grid - based on real activity pattern:
       Heavy commits: Nov-Dec 2025 (Inventory System capstone) & May-Jul 2026 (OJT/Clinic System)
       Months: Aug 2025 -> Sep 2026 (same as GitHub's trailing 53 weeks) */
    (function buildContribGrid() {
        const months = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
        const cw = document.getElementById('c-weeks');
        if (!cw) return;

        // Start from Aug 2025 (month index 7), display 53 weeks
        const START_MONTH = 7; // Aug
        const START_YEAR = 2025;
        const WEEKS = 53;

        // Define activity levels per week (0=none, 1=light, 2=moderate, 3=heavy, 4=very heavy)
        // Week 0 = first week of Aug 2025
        // Heavy periods:
        //   Nov-Dec 2025 = weeks ~13-22 (Inventory/Capstone project)
        //   May-Jul 2026 = weeks ~39-53 (OJT / Clinic System)
        const activityMap = [
            0, 0, 0, 0, 0, 0, 0, 0,  // Aug 2025 (wk 0-7) - no activity
            0, 0, 0, 0, 0,        // Sep-Oct 2025 (wk 8-12)
            1, 2, 2, 3, 3,        // Nov 2025 (wk 13-17) - capstone starts
            3, 4, 4, 2,          // Dec 2025 (wk 18-21) - heavy capstone
            1, 0, 0, 0,          // Jan 2026 (wk 22-25)
            0, 0, 0, 0,          // Feb 2026 (wk 26-29)
            0, 0, 0, 0,          // Mar 2026 (wk 30-33)
            0, 1, 1, 0,          // Apr 2026 (wk 34-37)
            2, 3, 4, 4,          // May 2026 (wk 38-41) - OJT starts
            4, 4, 3, 3,          // Jun 2026 (wk 42-45) - peak OJT
            3, 2, 2, 1,          // Jul 2026 (wk 46-49)
            1, 1, 0, 0           // Aug 2026 (wk 50-53)
        ];

        // Seeded random for day-level variation within a week
        let seed = 42;
        const rand = () => { seed = (seed * 1664525 + 1013904223) & 0xffffffff; return (seed >>> 0) / 0xffffffff; };

        let monthCursor = START_MONTH;
        let yearCursor = START_YEAR;
        let weekOfMonth = 0;

        for (let w = 0; w < WEEKS; w++) {
            const weekLevel = activityMap[w] !== undefined ? activityMap[w] : 0;
            const col = document.createElement('div'); col.className = 'week-col';

            for (let d = 0; d < 7; d++) {
                const cell = document.createElement('div'); cell.className = 'c-cell';
                if (weekLevel > 0) {
                    const r = rand();
                    // Vary per-day activity based on week level
                    const threshold = [1, 0.45, 0.3, 0.15, 0.05][weekLevel];
                    if (r > threshold) {
                        const lvl = r > 0.85 ? 'l4' : r > 0.65 ? 'l3' : r > 0.40 ? 'l2' : 'l1';
                        cell.classList.add(lvl);
                    }
                }
                col.appendChild(cell);
            }
            cw.appendChild(col);
        }
    })();

    /* Security */
    document.addEventListener('contextmenu', e => e.preventDefault());
    document.addEventListener('keydown', e => {
        if (e.key === 'F12') { e.preventDefault(); return false; }
        if (e.ctrlKey && e.shiftKey && ['I', 'J', 'C'].includes(e.key.toUpperCase())) { e.preventDefault(); return false; }
        if (e.ctrlKey && e.key.toUpperCase() === 'U') { e.preventDefault(); return false; }
    });
    document.addEventListener('dragstart', e => { if (e.target.tagName === 'IMG') e.preventDefault(); });

})();

